<script setup lang="ts">
import {ref,watch} from 'vue';
import {request,download,roleNames} from './model';
import type {Model,State} from './model';
interface Preview{revision:number;rows:{model:Model;line:number;existing:boolean}[];added:number;skipped:number}
const props=defineProps<{state:State}>();const emit=defineEmits<{saved:[state:State];busy:[value:boolean]}>();
const content=ref(''),fileName=ref(''),preview=ref<Preview>(),busy=ref(false),error=ref('');
const revision=props.state.revision;
watch(content,()=>preview.value=undefined);
defineExpose({draft:content});
async function read(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('文件不能超过2MiB');content.value=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());fileName.value=file.name;error.value=''}catch(e){error.value=e instanceof TypeError?'请另存为CSV UTF-8编码后导入':(e as Error).message}input.value=''}
async function submit(commit=false){if(busy.value)return;if(commit&&(!preview.value||preview.value.revision!==props.state.revision)){error.value='数据已变化，请返回后重新导入预览';return}busy.value=true;emit('busy',true);error.value='';try{if(commit)emit('saved',await request<State>('/models/import/commit','POST',{revision:preview.value!.revision,content:content.value}));else preview.value=await request<Preview>('/models/import/preview','POST',{revision,content:content.value})}catch(e){error.value=(e as Error).message;preview.value=undefined}finally{busy.value=false;emit('busy',false)}}
</script>
<template><form class="model-import" @submit.prevent="submit(!!preview)"><p class="panel-note">上传 CSV UTF-8，一次导入多个型号。相同定义自动跳过；同名型号参数冲突会提示核对，不覆盖现有型号。自定义角色请先在“管理角色”中添加。</p><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="import-file-actions"><label class="button secondary file-button">{{fileName||'选择型号CSV'}}<input type="file" accept=".csv" aria-label="上传型号CSV" @change="read"/></label><button type="button" class="text-button" @click="download('型号库导入模板.csv','\ufeff型号,厂商,设备角色,U高,端口说明\n示例防火墙,示例厂商,基础设施,2,8 × 10G\n','text/csv')">下载CSV模板</button><a class="text-button" href="/api/export/models.csv" download>导出现有型号</a></div><label class="full-label">CSV 内容<textarea v-model="content" rows="6" required spellcheck="false" placeholder="型号,厂商,设备角色,U高,端口说明"/></label><p class="field-note">必填：型号、设备角色（名称或标识）。U高为空或0表示待确认；最多2000个型号，文件不超过2MiB。</p><template v-if="preview"><p class="info-banner" role="status">将新增 {{preview.added}} 个型号，跳过 {{preview.skipped}} 个相同定义。</p><div class="table-scroll model-preview"><table><thead><tr><th>行</th><th>型号</th><th>角色</th><th>U高</th><th>处理</th></tr></thead><tbody><tr v-for="row in preview.rows" :key="row.line"><td>{{row.line}}</td><td>{{row.model.name}}</td><td>{{roleNames[row.model.role]}}</td><td>{{row.model.uHeight||'待确认'}}</td><td>{{row.existing?'跳过':'新增'}}</td></tr></tbody></table></div></template><div class="modal-actions"><span class="muted small">确认后全局型号库可用</span><button class="primary" :disabled="busy||!content.trim()||!!preview&&!preview.added">{{busy?'正在处理…':preview?'确认导入型号':'预览型号导入'}}</button></div></form></template>
